def add(sku: String) = Action { implicit request =>
  val items = request.session.get("cart").toList.flatMap(_.split(',')).filter(_.nonEmpty)
  Redirect(routes.Cart.show).withSession("cart" -> (items :+ sku).mkString(","))
}

